using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEngine.Profiling;
internal class CommandScript:IRunCommand{
 const string R="C:/Users/15352/Documents/Codex/2026-10-27/task-2/render-fix21/continuous47-counts/";
 [Serializable]class Header{public string scenePath;public bool sceneDirty;public string[]dirtyAssets;}
 [Serializable]class Done{public bool observerRemoved;public string restoreError;}
 [Serializable]class Receipt{public string utc,scenePath;public bool sceneDirty,normalStopRequested;public string[]dirty,unexpected;public long allocated,rtBytes;public int rtCount;}
 public void Execute(ExecutionResult r){if(!EditorApplication.isPlaying||!EditorApplication.isPaused||!File.Exists(R+"CAPTURE_DONE.json"))throw new Exception("Owned paused completed capture required");var before=JsonUtility.FromJson<Header>(File.ReadLines(R+"SCENE_BEFORE.ndjson").First());var done=JsonUtility.FromJson<Done>(File.ReadAllText(R+"CAPTURE_DONE.json"));if(!done.observerRemoved||!string.IsNullOrEmpty(done.restoreError))throw new Exception("Runtime restoration incomplete; do not hide by stopping");var scene=SceneManager.GetActiveScene();if(scene.path!=before.scenePath)throw new Exception("Scene changed; preserve state");var expected=before.dirtyAssets.ToHashSet();foreach(var path in new[]{"ProjectSettings/GraphicsSettings.asset","ProjectSettings/ProjectSettings.asset","ProjectSettings/QualitySettings.asset","ProjectSettings/TimeManager.asset"})expected.Add(path);var dirty=Resources.FindObjectsOfTypeAll<UnityEngine.Object>().Where(o=>o&&EditorUtility.IsPersistent(o)&&EditorUtility.IsDirty(o)).Select(AssetDatabase.GetAssetPath).Where(p=>!string.IsNullOrEmpty(p)&&(p.StartsWith("Assets/")||p.StartsWith("ProjectSettings/"))).Distinct().OrderBy(p=>p).ToArray();var unexpected=dirty.Where(p=>!expected.Contains(p)).ToArray();if(unexpected.Length>0)throw new Exception("Unexpected dirty assets; preserve: "+string.Join(",",unexpected));var rt=Resources.FindObjectsOfTypeAll<RenderTexture>();File.WriteAllText(R+"STOP_REQUEST.json",JsonUtility.ToJson(new Receipt{utc=DateTime.UtcNow.ToString("O"),scenePath=scene.path,sceneDirty=scene.isDirty,normalStopRequested=true,dirty=dirty,unexpected=unexpected,allocated=Profiler.GetTotalAllocatedMemoryLong(),rtBytes=rt.Sum(t=>Profiler.GetRuntimeMemorySizeLong(t)),rtCount=rt.Length},true));EditorApplication.isPlaying=false;r.Log("Normal Play exit requested after six-frame observer removal and runtime restore. No save/reload/force-clean. Runtime dirty="+dirty.Length+", unexpected=0.");}
}

